import{s}from"/dist/chunk-6k8ey1xy.js";function e(){return s("div",{class:"markdown-body",dangerouslySetInnerHTML:{__html:'<p>根据 openCode 的实现，当你提问"请给我的项目写一个 README.md"时，系统会使用以下全部 prompt：</p><hr /><h2>完整 Prompt 列表</h2><h3>1. <strong>系统级基础 Prompt</strong> (<code>system.ts</code>)</h3><h4>Provider 特定提示词（根据模型选择）：</h4><ul><li><a href="packages/opencode/src/session/prompt/anthropic.txt">anthropic.txt</a> - Claude 模型的基础提示词</li><li><a href="packages/opencode/src/session/prompt/beast.txt">beast.txt</a> - GPT 系列模型的基础提示词</li><li><a href="packages/opencode/src/session/prompt/gemini.txt">gemini.txt</a> - Gemini 模型的基础提示词</li><li><a href="packages/opencode/src/session/prompt/codex.txt">codex.txt</a> - Codex 专用提示词</li><li><a href="packages/opencode/src/session/prompt/qwen.txt">qwen.txt</a> - Qwen 模型提示词</li></ul><h4>Anthropic 专用头部：</h4><ul><li><a href="packages/opencode/src/session/prompt/anthropic_spoof.txt">anthropic_spoof.txt</a> - 欺骗性头部（如果 providerID 包含 "anthropic"）</li></ul><h4>Codex 指令：</h4><ul><li><a href="packages/opencode/src/session/prompt/codex_header.txt">codex_header.txt</a> - Codex 额外指令</li></ul><h3>2. <strong>环境信息 Prompt</strong> (动态生成)</h3><p>在 <a href="packages/opencode/src/session/system.ts#L38-L61">system.ts#L38-L61</a> 中生成：</p><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#E1E4E8">Here is some useful information about the environment you are running in:</span></span>\n<span class="line"><span style="color:#F97583">&#x3C;</span><span style="color:#E1E4E8">env</span><span style="color:#F97583">></span></span>\n<span class="line"><span style="color:#E1E4E8">  Working directory: ${Instance.directory}</span></span>\n<span class="line"><span style="color:#E1E4E8">  Is directory a git repo: ${project.vcs </span><span style="color:#F97583">===</span><span style="color:#9ECBFF"> "git"</span><span style="color:#F97583"> ?</span><span style="color:#9ECBFF"> "yes"</span><span style="color:#F97583"> :</span><span style="color:#9ECBFF"> "no"</span><span style="color:#E1E4E8">}</span></span>\n<span class="line"><span style="color:#E1E4E8">  Platform: ${process.platform}</span></span>\n<span class="line"><span style="color:#E1E4E8">  Today</span><span style="color:#9ECBFF">\'s date: ${new Date().toDateString()}</span></span>\n<span class="line"><span style="color:#9ECBFF">&#x3C;/env></span></span>\n<span class="line"><span style="color:#9ECBFF">&#x3C;files></span></span>\n<span class="line"><span style="color:#9ECBFF">  ${Ripgrep.tree(...)}  // 项目文件树</span></span>\n<span class="line"><span style="color:#9ECBFF">&#x3C;/files></span></span>\n<span class="line"></span></code></pre><h3>3. <strong>自定义规则 Prompt</strong> (<code>custom()</code>)</h3><p>在 <a href="packages/opencode/src/session/system.ts#L63-L139">system.ts#L63-L139</a> 中加载：</p><ul><li>项目根目录的 <code>AGENTS.md</code></li><li>项目根目录的 <code>CLAUDE.md</code></li><li>全局配置目录的 <code>AGENTS.md</code> (<code>~/.config/opencode/AGENTS.md</code>)</li><li>Claude Code 配置 <code>~/.claude/CLAUDE.md</code></li><li>配置文件中 <code>instructions</code> 字段指定的 URL 或文件</li></ul><h3>4. <strong>Agent 特定 Prompt</strong> (可选)</h3><p>如果使用的 Agent 有自定义 prompt（在 <a href="packages/opencode/src/session/prompt.ts#L63-L64">prompt.ts#L63-L64</a>）：</p><ul><li><a href="packages/opencode/src/agent/generate.txt">generate.txt</a> - 生成任务专用提示</li><li><a href="packages/opencode/src/agent/prompt/explore.txt">explore.txt</a> - 探索任务专用提示</li></ul><h3>5. <strong>会话控制 Prompt</strong> (条件插入)</h3><p>在 <a href="packages/opencode/src/session/prompt.ts#L600-L614">prompt.ts#L600-L614</a> 中，根据情况插入：</p><ul><li><a href="packages/opencode/src/session/prompt/plan.txt">plan.txt</a> - 如果是第一步，插入计划提示</li><li><a href="packages/opencode/src/session/prompt/build-switch.txt">build-switch.txt</a> - 构建/计划模式切换提示</li><li><a href="packages/opencode/src/session/prompt/max-steps.txt">max-steps.txt</a> - 如果达到最大步骤数（例如 <code>maxSteps: 5</code>）</li></ul><h3>6. <strong>用户消息包装 Prompt</strong> (loop 中)</h3><p>在 <a href="packages/opencode/src/session/prompt.ts#L529-L542">prompt.ts#L529-L542</a> 中：</p><pre class="shiki github-dark" style="background-color:#24292e;color:#e1e4e8" tabindex="0"><code><span class="line"><span style="color:#F97583">&#x3C;</span><span style="color:#E1E4E8">system</span><span style="color:#F97583">-</span><span style="color:#E1E4E8">reminder</span><span style="color:#F97583">></span></span>\n<span class="line"><span style="color:#E1E4E8">The user sent the following message:</span></span>\n<span class="line"><span style="color:#E1E4E8">请给我的项目写一个 README.md</span></span>\n<span class="line"><span style="color:#E1E4E8">Please address this message and </span><span style="color:#F97583">continue</span><span style="color:#E1E4E8"> with your tasks.</span></span>\n<span class="line"><span style="color:#F97583">&#x3C;/</span><span style="color:#E1E4E8">system</span><span style="color:#F97583">-</span><span style="color:#E1E4E8">reminder</span><span style="color:#F97583">></span></span>\n<span class="line"></span></code></pre><h3>7. <strong>工具描述 Prompt</strong> (工具注册时)</h3><p>每个可用工具都有自己的描述，在执行时作为工具定义的一部分（<a href="packages/opencode/src/session/prompt.ts#L600-L700">prompt.ts#L600-L700</a>）：</p><ul><li><a href="packages/opencode/src/tool/write.txt">write.txt</a> - 写文件工具</li><li><a href="packages/opencode/src/tool/read.txt">read.txt</a> - 读文件工具</li><li><a href="packages/opencode/src/tool/bash.txt">bash.txt</a> - 命令执行工具</li><li><a href="packages/opencode/src/tool/edit.txt">edit.txt</a> - 编辑工具</li><li>等等...</li></ul><hr /><h2>Prompt 组装顺序</h2><p>完整的 prompt 组装流程（<a href="packages/opencode/src/session/llm.ts#L60-L86">llm.ts#L60-L86</a>）：</p><ol><li>Header（anthropic_spoof，如果适用）</li><li>Provider 提示词 + Agent 提示词（二选一）</li><li>环境信息</li><li>自定义规则</li><li>用户消息包装</li><li>条件性插入的控制提示（plan、max-steps 等）</li></ol><p>这样，当你说"请给我的项目写一个 README.md"时，模型会看到：基础的 Agent 角色 + 项目上下文 + 工具能力 + 任务约束。</p><p>想深入了解 Agent 系统？看看 <a href="10-agent-types-and-modes-primary-agents-subagents-and-hidden-agents">Agent 类型和模式</a>。</p>'}},void 0,!1,void 0,this)}export{e as default};
